function addMoneyForm(){
  if(!parent()||state.cloud)return;
  modal('Add Money',`<p>This adds money to your family ledger, not a bank account.</p><form id="add-money-form"><label for="deposit-child">Child</label><select id="deposit-child">${childOptions()}</select>${field('deposit-amount','Amount','number','','min="0.01" max="1000000" step="0.01" required')}<p id="deposit-preview" aria-live="polite"></p>${field('deposit-reason','Reason (optional)','text','','maxlength="150"')}${field('deposit-pin','Parent passcode','password','','inputmode="numeric" required')}${formEnd('Add Money')}</form>`);
  const preview=()=>{try{const c=state.children.find(c=>c.id===$('#deposit-child').value),a=allocation(cents($('#deposit-amount').value),c.split);$('#deposit-preview').textContent=jars.map(j=>j[0].toUpperCase()+j.slice(1)+' '+c.split[j]+'%: '+money(a[j])).join(' · ');}catch{$('#deposit-preview').textContent='Enter an amount to preview the split.';}};
  $('#deposit-child').onchange=preview;$('#deposit-amount').oninput=preview;preview();
  let busy=false;
  $('#add-money-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const b=e.submitter;b.disabled=true;try{await unlock('parent',$('#deposit-pin').value);mutation(s=>addMoney(s,actor,$('#deposit-child').value,cents($('#deposit-amount').value),$('#deposit-reason').value),'Money added and split between jars.');}catch(err){error(err.message);}finally{busy=false;b.disabled=false;}};
}
