function viewAs(event){
  const selected=event.currentTarget.value;
  event.currentTarget.value=actor;
  if(!state||!actor||selected===actor)return;
  if(childAccess||!(selected==='parent'||state.children.some(c=>c.id===selected)))return;
  if($('#dialog').open&&$('#dialog-body form')&&!confirm('Leave this form and switch views? Unsaved edits will be lost.'))return;
  if(parent()&&selected!=='parent'){
    cloudGeneration++;actor=selected;page='Home';close();render();window.scrollTo(0,0);return;
  }
  // Selecting another profile never bypasses its existing passcode check.
  switchProfile();
  if($('#profile'))$('#profile').value=selected;
}
function updateViewAs(){
  closeViewAsMenu();
  let button=$('#view-as');
  if(!button){button=document.createElement('button');button.id='view-as';button.className='quiet';button.onclick=toggleViewAsMenu;document.body.append(button);}
  const activeProfile=!!(state&&actor);
  const label=`View as · ${!activeProfile?'Profile':parent()?'Parent':child()?.name||'Profile'} ▾`;
  button.hidden=!activeProfile;button.textContent=label;
  let dialogButton=$('#dialog-view-as');
  if(!dialogButton){dialogButton=document.createElement('button');dialogButton.id='dialog-view-as';dialogButton.className='quiet';dialogButton.onclick=toggleViewAsMenu;$('#dialog .dialog-head').append(dialogButton);}
  dialogButton.hidden=!activeProfile;dialogButton.textContent=label;
  for(const trigger of [button,dialogButton]){trigger.setAttribute('aria-haspopup','menu');trigger.setAttribute('aria-expanded','false');}
}
function closeViewAsMenu(focus=false){
  const menu=$('#view-as-menu');if(!menu)return;
  const trigger=document.getElementById(menu.dataset.trigger);
  menu.remove();trigger?.setAttribute('aria-expanded','false');if(focus)trigger?.focus();
}
function toggleViewAsMenu(event){
  const trigger=event.currentTarget,alreadyOpen=$('#view-as-menu')?.dataset.trigger===trigger.id;
  closeViewAsMenu();if(alreadyOpen||!state||!actor)return;
  const menu=document.createElement('div');menu.id='view-as-menu';menu.dataset.trigger=trigger.id;
  menu.setAttribute('role','menu');menu.setAttribute('aria-label','View as');
  const profiles=[...(childAccess?[]:[{id:'parent',name:'Parent'}]),...state.children.filter(c=>!childAccess||c.id===actor)];
  menu.innerHTML=profiles.map(c=>`<button type="button" role="menuitemradio" aria-checked="${c.id===actor}" data-view-profile="${esc(c.id)}"><span class="view-as-avatar" aria-hidden="true">${c.id==='parent'?'P':esc(c.name.slice(0,1))}</span><span>${esc(c.name)}</span><span class="view-as-check" aria-hidden="true">${c.id===actor?'✓':''}</span></button>`).join('');
  ($('#dialog').open?$('#dialog'):document.body).append(menu);
  const rect=trigger.getBoundingClientRect();menu.style.top=`${rect.bottom+8}px`;menu.style.right=`${Math.max(12,window.innerWidth-rect.right)}px`;menu.style.maxHeight=`${Math.max(80,window.innerHeight-rect.bottom-24)}px`;
  trigger.setAttribute('aria-expanded','true');
  const items=[...menu.querySelectorAll('button')];
  items.forEach(item=>item.onclick=()=>{const selected=item.dataset.viewProfile;closeViewAsMenu(true);viewAs({currentTarget:{value:selected}});});
  menu.onkeydown=e=>{const index=items.indexOf(document.activeElement);let next;
    if(e.key==='ArrowDown')next=(index+1)%items.length;
    if(e.key==='ArrowUp')next=(index+items.length-1)%items.length;
    if(e.key==='Home')next=0;if(e.key==='End')next=items.length-1;
    if(next!==undefined){e.preventDefault();items[next]?.focus();}
    if(e.key==='Escape'){e.preventDefault();e.stopPropagation();closeViewAsMenu(true);}
    if(e.key==='Tab')closeViewAsMenu();
  };
  (items.find(item=>item.dataset.viewProfile===actor)||items[0])?.focus();
}
document.addEventListener('pointerdown',event=>{if(!event.target.closest('#view-as-menu,#view-as,#dialog-view-as'))closeViewAsMenu();});
