  modal('Create a family',`<p>Start on this phone. No Mac needed.</p><button class="button-full" id="create-google" data-i18n="Continue with Google">Continue with Google</button><p class="subtle">Your family will sync across devices. Later, sign into the same account on your Mac.</p><button class="quiet button-full" id="create-local">Use this device only</button><p class="footer-note">Device-only families stay separate from your online family.</p><p id="form-error" role="alert"></p>`);
  $('#create-google').onclick=async()=>{try{if(cloudUser())await openCloud();else await googleSignIn();}catch(e){error(e.message);}};
