function forgotPassword(){
  const email=$('#cloud-email')?.value||'';
  modal('Reset your email password',`<p>For email-and-password sign-in only. Google users should choose Continue with Google.</p><form id="forgot-password">${field('reset-email','Email','email',email,'autocomplete="email" required')}${formEnd('Send reset link')}</form>`);
  $('#forgot-password').onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{await sendPasswordReset($('#reset-email').value);modal('Check your email',`<p>If an eligible account exists for that email, you’ll receive a reset link. Check your spam folder too.</p><button class="button-full" data-act="cloud-login">Back to sign in</button>`);}catch(e){error(e.message);button.disabled=false;}};
}
function resetPasswordForm(){
  modal('Choose a new password',`<form id="reset-password">${field('reset-new','New password','password','','autocomplete="new-password" minlength="8" required')}${field('reset-repeat','Repeat new password','password','','autocomplete="new-password" minlength="8" required')}${formEnd('Save new password')}</form>`);
  $('#reset-password').onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{if($('#reset-new').value!==$('#reset-repeat').value)throw Error('The passwords do not match.');await saveRecoveredPassword($('#reset-new').value);modal('Password updated',`<p>You can now sign in with your email and new password.</p><button class="button-full" data-act="cloud-login" data-i18n="Sign in">Sign in</button>`);}catch(e){error(e.message);button.disabled=false;}};
}
function cloudFamilyForm(){
  modal('Start your family',`<p>You’re signed in. Create your family here—no Mac needed. If you already belong to a family, use an invitation instead.</p><form id="create-cloud-family">${field('family-cloud-name','Family name','text','Our family','required maxlength="80"')}${field('family-parent-name','Your name','text','','required maxlength="80"')}${field('family-child-name','First child’s nickname','text','','required maxlength="40"')}<label for="family-currency">Currency</label><select id="family-currency">${['USD','GBP','EUR','CAD','AUD','NZD'].map(c=>`<option>${c}</option>`).join('')}</select><p>Starts with a weekly payday and a 50% Spend / 40% Save / 10% Give split. You can change these later in Settings and Family.</p>${formEnd('Create family')}</form><button class="quiet button-full" data-act="cloud-join">Join an existing family instead</button>`);
  $('#create-cloud-family').onsubmit=async event=>{
    event.preventDefault();const button=event.submitter;button.disabled=true;
    try{
      // Recheck after OAuth and before creation. Never replace an existing family.
      if(await loadCloudFamily()){await openCloud();return;}
      const snapshot=newCloudFamily({user:cloudUser(),name:$('#family-cloud-name').value,parentName:$('#family-parent-name').value,childName:$('#family-child-name').value,currency:$('#family-currency').value,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,locale:navigator.language});
      await rpc('create_family_account',{p_family_id:snapshot.family.id,p_name:snapshot.family.name,p_timezone:snapshot.family.timezone,p_currency:snapshot.family.currency,p_state:snapshot});
      await openCloud();
    }catch(e){error(e.message);}finally{button.disabled=false;}
  };
}
function cloudParentKey(){return 'cloud-parent:'+state.id;}
function cloudUnlock(){
  modal('Unlock your profile',`<p>You are still signed in. Enter your profile passcode.</p><form id="cloud-unlock">${field('unlock-cloud-pin','Passcode','password','','inputmode="numeric" required')}${formEnd('Unlock')}</form><button class="danger button-full" data-act="cloud-signout" data-i18n="Sign Out">Sign Out</button>`);
  $('#cloud-unlock').onsubmit=async e=>{e.preventDefault();try{
    if(childAccess){const pin=$('#unlock-cloud-pin').value;const row=await readChildConnection(childAccess.token,pin);childAccess.pin=pin;state=phoneView(row);actor=state.children[0].id;}
    else{await unlock(cloudParentKey(),$('#unlock-cloud-pin').value);actor='parent';}
    close();render();
  }catch(err){error(err.message);}};
}
function setupCloudPin(edit=false){
  const existing=!!readPins()[cloudParentKey()];
  if(existing&&!edit)return;
  if(actor!=='parent')return;
  const key=cloudParentKey(),generation=cloudGeneration;
  modal('Parent profile passcode',`<p>Choose a four-digit parent passcode for this phone. It protects profile unlock, payday and purchase approvals.</p><p class="subtle">Passcodes are set on each device. If you add a Mac later, you can choose the same passcode there.</p><form id="cloud-pin-setup">${existing?field('cloud-old-pin','Current phone parent passcode','password','','inputmode="numeric" required'):''}${field('cloud-new-pin','Parent passcode','password','','inputmode="numeric" pattern="[0-9]{4}" maxlength="4" required')}${field('cloud-repeat-pin','Repeat parent passcode','password','','inputmode="numeric" pattern="[0-9]{4}" maxlength="4" required')}${formEnd('Use this parent passcode')}</form>`);
  $('#cloud-pin-setup').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{
    if(existing)await unlock(key,$('#cloud-old-pin').value);
    const pin=$('#cloud-new-pin').value;
    if(!/^[0-9]{4}$/.test(pin))throw Error('Choose a four-digit parent passcode.');
    if(pin!==$('#cloud-repeat-pin').value)throw Error('The passcodes do not match.');
    const credential=await makePin(pin);
    if(generation!==cloudGeneration||actor!=='parent')return;
    const pins=readPins();pins[key]=credential;localStorage.setItem(PINKEY,JSON.stringify(pins));
    close();toast('Parent profile and actions now use this passcode on your phone.');
  }catch(e){error(e.message);}finally{button.disabled=false;}};
}

async function childJoin(initial=''){
  await disconnectCloud();
  if(initial){try{localStorage.setItem('pocketcrew.child-invitation',invitationToken(initial));}catch{}}
  modal('Open my child profile',`<p>Use the private link and separate passcode your parent gives you. Only your work, jars and history will open. You can start and submit your work. A parent reviews it.</p><form id="child-join">${field('child-link','Child invitation link','text',initial,'autocomplete="off" required')}${field('join-pin','Invitation passcode','password','','inputmode="numeric" pattern="[0-9]{6,8}" autocomplete="off" required')}${formEnd('Open my profile')}</form>`);
  $('#child-join').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;const generation=cloudGeneration;try{
    const token=invitationToken($('#child-link').value),pin=$('#join-pin').value;
    const row=await readChildConnection(token,pin);if(generation!==cloudGeneration)return;
    localStorage.setItem('pocketcrew.child-invitation',token);childAccess={token,pin};state=phoneView(row);actor=state.children[0].id;page='Home';close();render();
    clearInterval(cloudTimer);cloudTimer=setInterval(()=>refreshCloud(false),1000);
  }catch(e){error(e.message);}finally{if(e.submitter)e.submitter.disabled=false;}};
}
function childInvite(){
  if(!parent()||!state?.cloud||!cloudUser())return;
  modal('Connect a child’s device',`<p>Choose a child and a separate 6–8 digit invitation passcode. Do not use the parent passcode. Links expire after 30 days. The child can view only their own records; they cannot edit balances or approve purchases.</p><form id="invite-child"><label for="invite-child-id">Child</label><select id="invite-child-id">${childOptions()}</select>${field('invite-child-pin','New invitation passcode','password','','inputmode="numeric" pattern="[0-9]{6,8}" autocomplete="new-password" required')}${formEnd('Create private link')}</form><button class="quiet button-full" id="revoke-child">Revoke all links for the selected child</button>`);
  $('#invite-child').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;const generation=cloudGeneration;try{
    const result=await rpc('create_child_connection',{p_family_id:state.id,p_child_id:$('#invite-child-id').value,p_pin:$('#invite-child-pin').value});
    if(generation!==cloudGeneration)return;
    const link='https://pocket-crew.vercel.app/app/#child='+result.token;
    modal('Your private child link',`<p>Give this link only to the selected child. Share the passcode separately. The link expires ${esc(date(result.expiresAt))}.</p>${field('private-link','Invitation link','text',link,'readonly')}<button class="button-full" id="copy-child-link">Copy link</button><p class="subtle">On the child’s phone, open the link and enter the invitation passcode. No child email is needed. Close this window after sharing.</p>`);
    $('#copy-child-link').onclick=async()=>{try{await navigator.clipboard.writeText(link);toast('Link copied. Keep it private.');}catch{$('#private-link').select();toast('Select and copy the invitation link.');}};
  }catch(e){error(e.message);}finally{if(e.submitter)e.submitter.disabled=false;}};
  $('#revoke-child').onclick=()=>{const id=$('#invite-child-id').value;modal('Revoke child links?',`<p>All invitation links for this child will stop working. An open child view will lock on its next refresh. You can create a new link later.</p><button class="button-full" id="confirm-revoke">Revoke links</button><p id="form-error" role="alert"></p>`);$('#confirm-revoke').onclick=async e=>{e.target.disabled=true;try{await rpc('revoke_child_connections',{p_family_id:state.id,p_child_id:id});close();toast('Child links revoked.');}catch(err){error(err.message);e.target.disabled=false;}};};
}
function cloudLogin(){modal('Sign in to PocketCrew',`<p>Sign in with Google to create a family here, or open your existing family. No Mac is needed.</p><p class="subtle">Use the same account on a Mac later to open this family. Any device-local family stays separate and will not be overwritten.</p><button class="button-full" id="google-login" data-i18n="Continue with Google">Continue with Google</button><form id="email-login">${field('cloud-email','Parent email','email','','autocomplete="email" required')}${field('cloud-password','Password','password','','autocomplete="current-password" required')}${formEnd('Sign in with email')}</form><button class="quiet button-full" id="forgot-email-password" data-i18n="Forgot Password?">Forgot Password?</button>`);$('#forgot-email-password').onclick=forgotPassword;$('#google-login').onclick=()=>googleSignIn().catch(e=>error(e.message));$('#email-login').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{await emailSignIn($('#cloud-email').value.trim(),$('#cloud-password').value);await openCloud();}catch(e){error(e.message);}finally{button.disabled=false;}};}
async function openCloud(restored=false){const row=await loadCloudFamily();if(!row){cloudFamilyForm();return;}state=phoneView(row);actor=restored&&readPins()[cloudParentKey()]?null:'parent';page='Home';close();render();clearInterval(cloudTimer);cloudTimer=setInterval(()=>refreshCloud(false),1000);setupCloudPin();}
async function refreshCloud(manual=true){if(cloudBusy||!state?.cloud||!actor||document.hidden)return;cloudBusy=true;const generation=cloudGeneration;try{const row=childAccess?await readChildConnection(childAccess.token,childAccess.pin):await loadCloudFamily();if(generation!==cloudGeneration)return;if(!row)throw Error('Family access is no longer available. Sign out and ask a parent for help.');if(row.revision>state.revision){state=phoneView(row);if(!$('#dialog').open)render();}const status=$('#cloud-status');if(status)status.textContent='';if(manual)toast('Family is up to date.');}catch(e){if(generation!==cloudGeneration)return;if(childAccess){lock();toast('Could not refresh your child profile. '+e.message);}else{const status=$('#cloud-status');if(status)status.textContent='Could not refresh. '+e.message;}}finally{cloudBusy=false;}}
async function disconnectCloud(){localStorage.removeItem('pocketcrew.child-invitation');cloudGeneration++;childAccess=null;clearInterval(cloudTimer);cloudTimer=null;state=null;actor=null;close();render();try{await cloudSignOut();}catch{}try{state=JSON.parse(localStorage.getItem(KEY));}catch{}render();}
function joinCloud(){modal('Join with a parent invitation',`<p>Ask the family’s parent to invite your email from the Mac app’s Family page. Sign in with that invited email, then paste the invitation link or code here. Invitations give parent access—not child access.</p><form id="join-form">${field('invite-code','Invitation link or code','text','','autocomplete="off" required')}${formEnd('Join family')}</form>`);$('#join-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{let token=$('#invite-code').value.trim();if(token.includes('://'))token=new URL(token).searchParams.get('token')||'';if(!token)throw Error('Paste the invitation from your email.');await acceptFamilyInvite(token);await openCloud();}catch(e){error(e.message);}finally{if(e.submitter)e.submitter.disabled=false;}};}
try {state=JSON.parse(localStorage.getItem(KEY));if(state && state.version!==1)throw Error('Unknown data version');}catch{state=null;}
const parent=()=>actor==='parent', child=()=>state.children.find(c=>c.id===actor), visibleChildren=()=>parent()?state.children:state.children.filter(c=>c.id===actor);
const selectedChild=()=>child()??state.children[0];
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function modal(title,body){$('#dialog').classList.remove('shopping-dialog');$('#dialog-title').textContent=t(title);$('#dialog-body').innerHTML=body;$('#dialog').showModal();$('#dialog').querySelector('input,select,textarea')?.focus();}
function close(){$('#dialog').close();}
$('#close-dialog').onclick=close;
function error(message){const el=$('#form-error');if(el){el.textContent=message;el.setAttribute('role','alert');}else toast(message);}
async function mutation(fn,success){
  if(state?.cloud){toast('This action is available in the Mac app. Your cloud family was not changed.');return;}
  if(writeBusy)return;writeBusy=true;
  const operation=async()=>{
    const disk=JSON.parse(localStorage.getItem(KEY));
    if(!disk || disk.id!==state.id || disk.revision!==state.revision){state=disk;throw Error('This family changed in another tab. Review the latest version and try again.');}
    const copy=structuredClone(state);const result=fn(copy);copy.revision++;
    localStorage.setItem(KEY,JSON.stringify(copy));state=copy;return result;
  };
  try{const result=navigator.locks?await navigator.locks.request(KEY,operation):await operation();close();render();if(success)toast(success);return result;}
  catch(e){error(e.message);render();}finally{writeBusy=false;}
}
function field(name,label,type='text',value='',extra=''){return `<label for="${name}">${esc(t(label))}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>`;}
function childOptions(){return state.children.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');}
function splitFields(split={spend:50,save:40,give:10}){return `<fieldset class="split-group"><legend>Money split</legend><div class="split">${jars.map(j=>`<div class="split-field">${field(j,j[0].toUpperCase()+j.slice(1)+' %','number',split[j],'min="0" max="100" step="1" inputmode="numeric" required')}</div>`).join('')}</div><p id="split-total" class="muted" aria-live="polite">Total: ${jars.reduce((n,j)=>n+split[j],0)}% — must equal 100%</p></fieldset>`;}
function trackSplit(){for(const j of jars)$('#'+j).oninput=()=>{$('#split-total').textContent=`Total: ${jars.reduce((n,k)=>n+Number($('#'+k).value),0)}% — must equal 100%`;};}
function formEnd(button){return `<p id="form-error" class="error" role="alert"></p><button class="button-full" type="submit">${esc(t(button))}</button>`;}
async function digest(pin,salt){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(pin),'PBKDF2',false,['deriveBits']);const data=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:150000,hash:'SHA-256'},key,256);return Array.from(new Uint8Array(data),v=>v.toString(16).padStart(2,'0')).join('');}
async function makePin(pin){if(!/^\d{4,8}$/.test(pin))throw Error('Use a passcode with 4–8 digits.');const salt=uid();return {salt,hash:await digest(pin,salt)};}
function readPins(){return JSON.parse(localStorage.getItem(PINKEY)||'{}');}
async function unlock(id,pin){
  const pins=readPins(),p=pins[id];if(!p)throw Error('This profile needs a passcode. Ask your parent to reset it.');
  if(p.until>Date.now())throw Error('Please wait a minute before trying again.');
  if(await digest(pin,p.salt)!==p.hash){p.failures=(p.failures||0)+1;if(p.failures>=5){p.until=Date.now()+60000;p.failures=0;}localStorage.setItem(PINKEY,JSON.stringify(pins));throw Error('That passcode does not match. Try again.');}
  p.failures=0;p.until=0;localStorage.setItem(PINKEY,JSON.stringify(pins));
}
function lock(){if(state?.cloud){cloudGeneration++;actor=null;close();render();return;}actor=null;page='Home';close();render();}
function switchProfile(){if(parent()&&!state?.cloud){modal('View as a child',`<p>You already unlocked the parent profile. Choose a child—no child passcode is needed. Returning to parent controls still requires your parent passcode.</p>${state.children.map(c=>`<button class="quiet button-full" data-parent-preview="${c.id}">${esc(c.name)}</button>`).join('')}`);document.querySelectorAll('[data-parent-preview]').forEach(b=>b.onclick=()=>{if(!parent())return;actor=b.dataset.parentPreview;page='Home';close();render();});return;}if(state?.cloud){cloudUnlock();return;}modal('Who’s here?',`<p>Choose your profile and enter its passcode.</p>${state.demo?'<p class="subtle">Demo passcodes: Maya 1234 · Jordan 1111 · Riley 2222. These protect sample data only.</p>':''}<form id="unlock"><label for="profile" data-i18n="Profile">Profile</label><select id="profile"><option value="parent">${state.demo?'Maya · ':''}Parent</option>${childOptions()}</select>${field('pin','Passcode','password','','inputmode="numeric" pattern="[0-9]{4,8}" autocomplete="off" required')}${formEnd('Open profile')}</form>`);$('#unlock').onsubmit=async e=>{e.preventDefault();try{await unlock($('#profile').value,$('#pin').value);actor=$('#profile').value;page='Home';close();render();}catch(e){error(e.message);}};}
async function startDemo(){try{if(state)throw Error('A family is already saved on this device.');const pins={parent:await makePin('1234'),jordan:await makePin('1111'),riley:await makePin('2222')};localStorage.setItem(PINKEY,JSON.stringify(pins));state=demo();localStorage.setItem(KEY,JSON.stringify(state));actor='parent';render();toast('Demo ready! Switch profiles to try the child view.');}catch(e){toast('Could not save on this device. '+e.message);}}
function localNewFamily(){modal('Start your crew',`<p>No email or Apple account needed. This family stays in this browser on this device; it does not sync with the Mac app.</p><form id="setup">${field('family-name','Family name','text','Our family','maxlength="60" required')}${field('parent-pin','Parent passcode','password','','inputmode="numeric" pattern="[0-9]{4,8}" required')}${field('child-name','First child’s nickname','text','','maxlength="40" required')}${field('child-pin','Child passcode (different from parent)','password','','inputmode="numeric" pattern="[0-9]{4,8}" required')}${splitFields()}${formEnd('Create family')}</form>`);trackSplit();$('#setup').onsubmit=async e=>{e.preventDefault();try{if($('#parent-pin').value===$('#child-pin').value)throw Error('Choose different parent and child passcodes.');const split=Object.fromEntries(jars.map(j=>[j,Number($('#'+j).value)]));validateSplit(split);const s=fresh($('#family-name').value.trim());if(!s.name||!$('#child-name').value.trim())throw Error('Enter a family name and child nickname.');const c={id:uid(),name:$('#child-name').value.trim(),split};s.children.push(c);const pins={parent:await makePin($('#parent-pin').value),[c.id]:await makePin($('#child-pin').value)};localStorage.setItem(PINKEY,JSON.stringify(pins));localStorage.setItem(KEY,JSON.stringify(s));state=s;actor='parent';close();page='Work';render();showPresets();}catch(e){error(e.message);}};}
function jarCards(c){return `<div class="jars">${jars.map((j,i)=>`<div class="jar"><span class="symbol" aria-hidden="true">${['◈','❧','♡'][i]}</span><span>${j[0].toUpperCase()+j.slice(1)}</span><strong>${money(balance(state,c.id,j))}</strong></div>`).join('')}</div>`;}
function goalCards(){return visibleChildren().map(c=>state.goals.filter(g=>g.childId===c.id&&g.status!=='archived').map(g=>{const progress=goalProgress(state,g);return `<article class="card">${g.shoppingProduct?productArt(g.shoppingProduct,esc):''}<div class="row"><h3>${esc(g.title)}</h3><span class="tag">${g.status==='completed'?'Completed ✓':g.status==='proposed'?'Waiting for a grown-up':progress.percent>=100?'Target reached!':esc(c.name)}</span></div>${g.shoppingProduct?.merchant?`<p class="muted">Sold by ${esc(g.shoppingProduct.merchant)}</p>`:''}<p class="muted">${money(progress.amount)} of ${money(g.target)}</p><div class="progress"><progress aria-label="${esc(g.title)} progress" value="${progress.amount}" max="${g.target}"></progress></div><small>${progress.percent}% · ${money(progress.remaining)} to go${g.featured?' · Big goal · Uses your Spend jar':''}${g.targetDate?' · '+date(g.targetDate):''}</small>${(!g.status||g.status==='active')&&g.saved<g.target&&!g.featured?`<button class="quiet button-full" data-act="feature-goal" data-id="${g.id}" data-i18n="Make my big goal">Make my big goal</button>`:''}${parent()&&!state.cloud&&(!g.status||g.status==='active')?`<button class="button-full" data-act="complete-goal" data-id="${g.id}" data-i18n="Complete goal">Complete goal</button>`:''}<button class="danger button-full" data-act="remove-goal" data-id="${g.id}" data-i18n="Remove goal">Remove goal</button>${parent()&&g.status==='proposed'?`<button class="quiet button-full" data-act="review-shopping-goal" data-id="${g.id}">Review goal</button>`:''}</article>`;}).join('')).join('');}
function workCards(items){if(!items.length)return '<div class="empty">Nothing here yet. Your next small contribution can start something good.</div>';return items.map(w=>{
  const c=state.children.find(c=>c.id===w.childId);let buttons='';
  if(parent()&&w.status==='awaitingApproval')buttons=`<button data-act="review" data-id="${w.id}">Check task</button>`;
  if(!parent()&&['assigned','available','redoRequested'].includes(w.status))buttons=`<button data-act="start" data-id="${w.id}">${w.status==='available'?'Claim gig':w.status==='redoRequested'?'Try again':'Start work'}</button>`;
  if(!parent()&&w.status==='inProgress')buttons=`<button data-act="submit" data-id="${w.id}" data-i18n="Send to my grown-up">Send to my grown-up</button>`;
  return `<article class="work"><div class="row"><span class="tag ${w.type}">${w.type==='gig'?'Paid gig':'Responsibility'}</span>${w.type==='gig'?`<span class="reward">${money(w.acceptedReward??w.reward)}</span>`:''}</div><h3>${esc(w.title)}</h3><p>${esc(w.instructions)}</p><small>${esc(labels[w.status])}${state.children.length>1?' · '+esc(c?.name??'Open to any child'):''}${w.due?' · '+date(w.due):''}</small>${w.reason?`<p class="note">Parent note: ${esc(w.reason)}</p>`:''}${buttons?`<div class="actions">${buttons}</div>`:''}</article>`;}).join('');}
function paydayCard(){const total=visibleChildren().reduce((n,c)=>n+pending(state,c.id),0);return `<article class="card payday"><div class="row"><span class="eyebrow">Next payday</span><span>✦</span></div><div class="amount">${money(total)}</div><p>Approved and waiting for ${date(state.nextPayday)}</p><button data-page="Payday">${parent()?'Review payday':'See my money split'}</button></article>`;}
function home(){const items=state.work.filter(w=>parent()?w.status==='awaitingApproval':w.childId===actor&&['assigned','inProgress','redoRequested'].includes(w.status));return `<span class="eyebrow">${esc(new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}))}</span><h1>${parent()?'A little work.<br>A lot of growing.':'Hi, '+esc(child().name)+' ☀'}</h1><p class="muted">${parent()?'Your crew’s next good habit starts here.':'Ready for your next small win?'}</p><div class="grid"><div>${paydayCard()}${!parent()?jarCards(child()):`<article class="card"><h2 data-i18n="Your crew">Your crew</h2>${state.children.map(c=>`<div class="row work"><div class="who"><span class="avatar">${esc(c.name[0])}</span><strong>${esc(c.name)}</strong></div><span>${money(pending(state,c.id))} pending</span></div>`).join('')}<button class="quiet button-full" data-act="add-child" data-i18n="Add Child">Add Child</button></article>`}</div><div><article class="card"><div class="row"><h2>${parent()?'Needs your review':'Today'}</h2><span class="tag">${items.length}</span></div>${workCards(items.slice(0,4))}<button class="quiet button-full" data-page="Work" data-i18n="All tasks">All tasks</button></article></div></div>${parent()?'<button class="quiet button-full" data-page="Jars">View jars & goals</button>':goalCards()}`;}
function workPage(){let items=state.work.filter(w=>parent()||w.childId===actor||w.status==='available');if(tab==='Available gigs')items=items.filter(w=>w.status==='available');else if(tab==='Completed')items=items.filter(w=>['approved','paid','rejected'].includes(w.status));else items=items.filter(w=>!['approved','paid','rejected','available'].includes(w.status));return `<span class="eyebrow">Small jobs, real skills</span><h1>Work together.</h1>${parent()?`<div class="actions"><button data-act="create-work" data-i18n="Add work">Add work</button><button class="quiet" data-act="presets" data-i18n="Get ideas">Get ideas</button></div>${!state.presetsDone?'<p class="banner">Need ideas? Choose a preset, edit it, and assign it to your crew.</p>':''}`:''}<div class="tabs" aria-label="Work filters">${['My work','Available gigs','Completed'].map(t=>`<button data-tab="${t}" class="${tab===t?'active':''}" aria-pressed="${tab===t}">${t}</button>`).join('')}</div><section class="card">${workCards(items)}</section>`;}
function paydayPage(){const kids=visibleChildren(),total=kids.reduce((n,c)=>n+pending(state,c.id),0);return `<span class="eyebrow">Earn it. Split it. Grow it.</span><h1>Make it payday.</h1><p class="muted">Weekly · Next payday ${date(state.nextPayday)}</p>${kids.map(c=>{const amount=pending(state,c.id),a=allocation(amount,c.split);return `<article class="card"><div class="row"><h2>${esc(c.name)}</h2><strong class="reward">${money(amount)}</strong></div><p class="muted">Approved earnings only. Work still awaiting review is not included.</p>${state.earnings.filter(e=>e.childId===c.id&&!e.paydayId).map(e=>`<div class="row work"><span>${esc(state.work.find(w=>w.id===e.workId)?.title??'Gig')}</span><strong>${money(e.amount)}</strong></div>`).join('')||'<p>No approved earnings yet.</p>'}<div class="jars">${jars.map(j=>`<div class="jar"><span>${j[0].toUpperCase()+j.slice(1)} · ${c.split[j]}%</span><strong>${money(a[j])}</strong></div>`).join('')}</div></article>`;}).join('')}${parent()?`<button class="button-full" data-act="payday" ${!total?'disabled':''}>${state.nextPayday>localDate()?'Review early payday':'Review payday'} · ${money(total)}</button>`:''}<section class="card"><h2>Past paydays</h2>${state.paydays.length?state.paydays.slice().reverse().map(p=>`<div class="row work"><span>${date(p.at)}</span><strong>${money(parent()?p.total:p.lines.filter(l=>l.childId===actor).reduce((n,l)=>n+l.gross,0))}</strong></div>`).join(''):'<p class="muted">Your first payday receipt will appear here.</p>'}</section>`;}
function jarPage(){const ids=visibleChildren().map(c=>c.id),entries=state.ledger.filter(t=>ids.includes(t.childId)&&(ledgerFilter==='all'||t.jar===ledgerFilter||t.category===ledgerFilter)&&t.description.toLowerCase().includes(search.toLowerCase()));return `<span class="eyebrow">Every little bit counts</span><h1>Your money, with purpose.</h1>${visibleChildren().map(c=>`<h2>${esc(c.name)}</h2>${jarCards(c)}`).join('')}${parent()?'<div class="actions"><button data-act="add-money" data-i18n="Add Money">Add Money</button><button data-act="purchase" data-i18n="Record spending">Record spending</button><button class="quiet" data-act="goal" data-i18n="Add goal">Add goal</button></div>':''}<h2 data-i18n="Your goals">Your goals</h2>${goalCards()||'<p class="muted">Parents can add a goal to start saving toward something special.</p>'}<article class="card"><h2 data-i18n="History">History</h2><label for="history-search">Find something in your jars</label><input id="history-search" type="search" value="${esc(search)}" placeholder="Payday, book, gift…"><label for="history-filter">Filter</label><select id="history-filter">${['all','payday',...jars,'adjustment'].map(j=>`<option value="${j}" ${ledgerFilter===j?'selected':''}>${j[0].toUpperCase()+j.slice(1)}</option>`).join('')}</select><div id="entries">${entries.slice().reverse().map(t=>`<div class="transaction"><div><b>${esc(t.description)}</b><small>${date(t.at)} · ${esc(state.children.find(c=>c.id===t.childId)?.name)} · ${t.jar}</small></div><strong>${t.amount>=0?'+':'−'}${money(Math.abs(t.amount))}</strong></div>`).join('')||'<p class="empty">No transactions match.</p>'}</div></article>`;}
function settingsPage(){return `${languageSettings()}<span class="eyebrow" data-i18n="Your crew">Your crew</span><h1 data-i18n="Settings">Settings</h1>${state.cloud?cloudBanner(esc,cloudUser()?.email||'',!!childAccess):'<article class="card"><h2>Saved on this device</h2><p>This family is saved on this device only.</p><button class="quiet" data-act="cloud-login" data-i18n="Connect family">Connect family</button></article>'}${parent()?'<article class="card"><h2 data-i18n="Payday schedule">Payday schedule</h2><button class="quiet" data-act="schedule" data-i18n="Edit payday schedule">Edit payday schedule</button></article>':''}<article class="card"><h2 data-i18n="App updates">App updates</h2><p>Check online for the latest PocketCrew version. Your family and sign-in stay saved.</p><button class="quiet" data-act="check-updates" data-i18n="Check for updates">Check for updates</button></article><article class="card"><h2 data-i18n="Learn PocketCrew">Learn PocketCrew</h2><button class="quiet" data-act="walkthrough" data-i18n="Take a tour">Take a tour</button></article><article class="card"><h2 data-i18n="Profiles">Profiles</h2><button class="quiet" data-act="lock" data-i18n="Lock profiles">Lock profiles</button></article>`;}
function profilePage(){return `<span class="eyebrow">${esc(state.name)}</span><h1>${parent()?'Family settings':'My profile'}</h1><p class="subtle">${state.demo?'This is the demo family.':'This family is saved only in this browser on this device.'} No Mac sync or Google sign-in in this phone preview. Deleting browser data removes this copy. Home Screen storage may be separate from Safari.</p>${visibleChildren().map(c=>`<article class="card"><h2>${esc(c.name)}</h2><p>${c.split.spend}% Spend · ${c.split.save}% Save · ${c.split.give}% Give</p>${parent()?`<div class="actions"><button class="quiet" data-act="edit-child" data-id="${c.id}">Edit child & split</button><button class="quiet" data-act="reset-pin" data-id="${c.id}">Reset passcode</button><button class="danger" data-act="remove-child" data-id="${c.id}" data-i18n="Remove child">Remove child</button></div>`:''}</article>`).join('')}${parent()?`<div class="actions"><button data-act="add-child" data-i18n="Add Child">Add Child</button><button class="quiet" data-act="schedule">Set payday</button></div><div class="actions"><button class="quiet" data-act="export">Export family backup</button><button class="quiet" data-act="reset-pin" data-id="parent" data-i18n="Parent passcode">Parent passcode</button></div><button class="danger button-full" data-act="delete">Delete this device’s family</button>`:''}<button class="quiet button-full" data-act="lock" data-i18n="Lock profiles">Lock profiles</button><p class="footer-note">Passcodes help keep profiles separate on a shared device. They are not encryption or separate online accounts. Use your device’s screen lock too.</p>`;}
installLanguage(()=>render());
function render(){
  updateViewAs();
  queueMicrotask(()=>walkthrough?.refresh());
  document.body.classList.toggle('welcome-screen',!state);
  document.body.classList.toggle('app-screen',!!actor);
  if(!state){$('#nav').innerHTML='';$('#main').innerHTML=welcome();return;}
  if(!actor){$('#nav').innerHTML='';$('#main').innerHTML=`<section class="welcome"><span class="eyebrow">${esc(state.name)}</span><h1>Welcome back,<br>crew.</h1><p>Unlock your profile to pick up where you left off.</p><button class="button-full" data-act="switch">Choose your profile</button><p class="footer-note">${state.demo?'Demo: parent 1234, Jordan 1111, Riley 2222.':'Ask your parent if you need help with your passcode.'}</p></section>`;}
else {$('#main').innerHTML=`<div class="profilebar"><div class="who"><span class="avatar">${parent()?'P':esc(child().name[0])}</span><div><b>${parent()?'Parent':esc(child().name)}</b><small class="muted"> · ${esc(state.name)}</small></div></div></div><p class="save-status">${state.demo?'Demo family':'Saved on this device'} · Saved on this device only</p>${sectionTabs(page,parent())}${({Home:home,Work:workPage,Payday:paydayPage,Jars:jarPage,Profile:profilePage,Settings:settingsPage})[page]()}<p class="footer-note">PocketCrew is a family tracker, not a bank. No real money is held or sent.</p>`;$('#nav').innerHTML=['Home','Work','Jars','Settings'].map((p,i)=>`<button data-page="${p}" ${p===mainSection(page)?'aria-current="page"':''}><span aria-hidden="true">${['⌂','✓','◈','⚙'][i]}</span>${t(p==='Work'?(parent()?'Tasks':'My Tasks'):p==='Jars'?(parent()?'Family Jars':'My Jars'):p)}</button>`).join('');}
  finishTheme(state,actor,page);
  if(state?.cloud){finishCloudView(state,!!childAccess||cloudPreview());if(cloudPreview()){$('.save-status').textContent='Child view preview · Return to Parent to make changes';document.querySelectorAll('main button[data-act="start"],main button[data-act="submit"]').forEach(b=>b.remove());}}
  else if(state&&actor&&page==='Settings'){$('#main').insertAdjacentHTML('beforeend','<button class="quiet button-full" data-act="child-join">Join with child link</button>');}
  if($('#history-search'))$('#history-search').onchange=e=>{search=e.target.value;render();};if($('#history-filter'))$('#history-filter').onchange=e=>{ledgerFilter=e.target.value;render();};
}
function workForm(preset){if(!parent())return;const p=preset??['','gig',100,''];modal(preset?'Make this idea yours':'Add work',`<form id="work-form"><label for="type">Type</label><select id="type"><option value="gig" ${p[1]==='gig'?'selected':''}>Paid gig</option><option value="responsibility" ${p[1]==='responsibility'?'selected':''}>Responsibility (unpaid)</option></select>${field('title','Title','text',p[0],'maxlength="100" required')}<label for="instructions">Instructions</label><textarea id="instructions" maxlength="1000">${esc(p[3])}</textarea><label for="assignee">Assign to</label><select id="assignee">${childOptions()}<option value="">Open to any child</option></select>${field('reward','Reward ($) — paid gigs only','number',(p[2]/100).toFixed(2),'min="0.01" step="0.01" max="100000"')}${field('due','Due date','date',localDate(),'required')}<p class="muted">One-time work. Choose a new preset again for the next job.</p>${formEnd('Add to the work list')}</form>`);const update=()=>{$('#reward').disabled=$('#type').value!=='gig';};$('#type').onchange=update;update();$('#work-form').onsubmit=e=>{e.preventDefault();try{const data={type:$('#type').value,title:$('#title').value,instructions:$('#instructions').value,childId:$('#assignee').value,reward:$('#type').value==='gig'?cents($('#reward').value):0,due:$('#due').value};mutation(s=>createWork(s,actor,data),'Work added.');}catch(e){error(e.message);}};}
function showPresets(){if(!parent())return;modal('A little inspiration',`<p>Choose an idea to edit its name, reward and child. Paid presets are all under $3.</p><div class="presets-scroll">${presetSections(esc,money)}</div><button class="button-full" id="presets-done">Done!</button>`);$('#presets-done').onclick=()=>mutation(s=>{s.presetsDone=true;},'You can always reopen ideas with “Show presets” in Tasks.');}
function childForm(id){if(!parent())return;const c=state.children.find(c=>c.id===id);modal(c?'Edit child':'Add Child',`<form id="child-form">${field('name','Nickname','text',c?.name??'','maxlength="40" required')}${!c?field('new-pin','Child passcode','password','','inputmode="numeric" pattern="[0-9]{4,8}" required'):''}${splitFields(c?.split)}${formEnd(c?'Save child settings':'Add Child')}</form>`);trackSplit();$('#child-form').onsubmit=async e=>{e.preventDefault();try{const split=Object.fromEntries(jars.map(j=>[j,Number($('#'+j).value)]));validateSplit(split);const name=$('#name').value.trim();if(!name)throw Error('Enter a nickname.');const newId=c?.id??uid();if(!c){const pins=readPins();pins[newId]=await makePin($('#new-pin').value);localStorage.setItem(PINKEY,JSON.stringify(pins));}await mutation(s=>{if(c){const target=s.children.find(x=>x.id===id);target.name=name;target.split=split;}else s.children.push({id:newId,name,split});},'Child settings saved.');}catch(e){error(e.message);}};}
function removeChildForm(id){if(!parent()||state.cloud)return;const c=state.children.find(c=>c.id===id);if(!c)return;const family=state.id;
modal('Remove '+c.name+'?',`<p>This removes their profile from this device’s family. Past records are kept in your family backup. Settle their balances, pending earnings, open work and cart first. At least one child must remain.</p><form id="remove-child-form">${field('remove-child-pin','Parent passcode','password','','required inputmode="numeric"')}<label class="check"><input type="checkbox" required>I want to remove this child.</label>${formEnd('Remove child')}</form>`);
$('#remove-child-form').onsubmit=async e=>{e.preventDefault();try{await unlock('parent',$('#remove-child-pin').value);if(!parent()||state?.id!==family)throw Error('Unlock the parent profile again.');await mutation(s=>removeChild(s,actor,id),'Child removed. Past records kept in family backup.');}catch(err){error(err.message);}};}
function submitForm(id){modal('Ready for a parent?',`<p>Check your work and tell your parent how it went.</p><form id="submit-form"><label for="note">A short note (optional)</label><textarea id="note" maxlength="1000" placeholder="I finished and put everything away."></textarea><label class="check"><input type="checkbox" required> I checked my work.</label>${formEnd('Send to my grown-up')}</form>`);$('#submit-form').onsubmit=e=>{e.preventDefault();const note=$('#note').value;mutation(s=>submitWork(s,actor,id,note),'Nice work! Your parent can review it now.');};}
function reviewForm(id){if(!parent())return;const w=state.work.find(w=>w.id===id);modal('Review work',`<h3>${esc(w.title)}</h3><p>${esc(w.instructions)}</p><p class="note">${esc(w.note||'No note added.')}</p><p>${w.type==='gig'?money(w.acceptedReward??w.reward)+' will go to pending earnings.':'An unpaid responsibility. No money will be added.'}</p><form id="review-form"><label for="decision">Decision</label><select id="decision"><option value="approved">Approve</option><option value="redoRequested">Request a redo</option><option value="rejected">Reject</option></select><label for="reason">Kind, specific reason (required for redo or rejection)</label><textarea id="reason" maxlength="1000"></textarea>${formEnd('Save review')}</form>`);$('#review-form').onsubmit=e=>{e.preventDefault();const decision=$('#decision').value,reason=$('#reason').value;mutation(s=>review(s,actor,id,decision,reason),'Review saved.');};}
function paydayForm(){if(!parent())return;paydayKey=uid();const total=state.children.reduce((n,c)=>n+pending(state,c.id),0);modal(state.nextPayday>localDate()?'Confirm early payday':'Confirm payday',`<p>Post <strong>${money(total)}</strong> of approved earnings to your children’s jars. Unreviewed work stays out. No real money moves.</p><form id="payday-form">${field('confirm-pin','Parent passcode','password','','inputmode="numeric" required')}${formEnd('Pay now')}</form>`);$('#payday-form').onsubmit=async e=>{e.preventDefault();try{await unlock('parent',$('#confirm-pin').value);const receipt=await mutation(s=>runPayday(s,actor,paydayKey));if(receipt)modal('Payday, made!',`<div class="receipt"><div class="big">✦</div><h1>${money(receipt.total)}</h1><p>Earned, split, and ready to grow.</p>${receipt.lines.map(l=>`<h3>${esc(state.children.find(c=>c.id===l.childId).name)}</h3><div class="jars">${jars.map(j=>`<div class="jar"><span>${j}</span><strong>${money(l.amounts[j])}</strong></div>`).join('')}</div>`).join('')}<p>Your receipt and jar entries are saved in History.</p></div>`);}catch(e){error(e.message);}};}
function purchaseForm(){if(!parent())return;modal('Record a purchase or withdrawal',`<p>This records a payment your family handled outside PocketCrew. It does not buy anything.</p><form id="purchase-form"><label for="buyer">Child</label><select id="buyer">${childOptions()}</select><label for="jar">Jar</label><select id="jar"><option value="spend">Spend — purchase</option><option value="save">Save — withdrawal</option><option value="give">Give — gift</option></select>${field('amount','Amount ($)','number','','min="0.01" step="0.01" required')}${field('reason','What was it for / where did it go?','text','','maxlength="150" required')}${field('confirm-pin','Parent passcode','password','','inputmode="numeric" required')}${formEnd('Confirm deduction')}</form>`);$('#purchase-form').onsubmit=async e=>{e.preventDefault();try{await unlock('parent',$('#confirm-pin').value);const c=$('#buyer').value,j=$('#jar').value,a=cents($('#amount').value),r=$('#reason').value;mutation(s=>purchase(s,actor,c,j,a,r),'Recorded in History.');}catch(e){error(e.message);}};}
function goalForm(){if(!parent())return;modal('Something to save for',`<form id="goal-form"><label for="owner">Child</label><select id="owner">${childOptions()}</select>${field('goal-title','Goal name','text','','maxlength="80" required')}${field('target','Target amount ($)','number','','min="0.01" step="0.01" required')}<p>New Save deposits go toward this featured goal. Existing savings stay where they are.</p>${formEnd('Create featured goal')}</form>`);$('#goal-form').onsubmit=e=>{e.preventDefault();try{const childId=$('#owner').value,title=$('#goal-title').value.trim(),target=cents($('#target').value);if(!title||!target)throw Error('Add a name and a positive target.');mutation(s=>{s.goals.filter(g=>g.childId===childId).forEach(g=>g.featured=false);s.goals.push({id:uid(),childId,title,target,saved:0,featured:true});},'Your goal is ready.');}catch(e){error(e.message);}};}
function pinForm(id){if(!parent())return;modal('Reset profile passcode',`<form id="pin-form">${field('old-pin','Current parent passcode','password','','inputmode="numeric" required')}${field('new-pin','New passcode for '+(id==='parent'?'parent':esc(state.children.find(c=>c.id===id).name)),'password','','inputmode="numeric" pattern="[0-9]{4,8}" required')}${formEnd('Save passcode')}</form>`);$('#pin-form').onsubmit=async e=>{e.preventDefault();try{await unlock('parent',$('#old-pin').value);const pins=readPins();pins[id]=await makePin($('#new-pin').value);localStorage.setItem(PINKEY,JSON.stringify(pins));close();toast('Passcode updated on this device.');}catch(e){error(e.message);}};}
function scheduleForm(){
  if(!parent())return;
  modal('Payday schedule',`<form id="schedule-form"><label for="payday-frequency">Frequency</label><select id="payday-frequency"><option value="weekly">Weekly</option><option value="custom">Custom</option></select><div id="custom-days-row"><label for="payday-days">Every</label><input id="payday-days" type="number" min="1" max="365" step="1" value="${Number(state.customDays)||7}" required><span>days</span></div>${field('payday-date','Next payday','date',state.nextPayday,'required')}${formEnd('Save schedule')}</form>`);
  $('#payday-frequency').value=state.frequency==='custom'?'custom':'weekly';
  const update=()=>{$('#custom-days-row').hidden=$('#payday-frequency').value!=='custom';$('#payday-days').disabled=$('#payday-frequency').value!=='custom';};
  $('#payday-frequency').onchange=update;update();
  $('#schedule-form').onsubmit=e=>{e.preventDefault();const d=$('#payday-date').value,frequency=$('#payday-frequency').value,days=Number($('#payday-days').value);if(frequency==='custom'&&(!Number.isInteger(days)||days<1||days>365)){error('Enter a whole number from 1 to 365 days.');return;}mutation(s=>{s.nextPayday=d;s.frequency=frequency;s.customDays=frequency==='custom'?days:null;},'Payday schedule saved.');};
}
function deleteForm(){if(!parent())return;modal('Delete this device’s family?',`<p>This removes this browser’s work, balances and history. It does not delete a Mac or cloud family. Export a backup first if you want to keep a record.</p><form id="delete-form">${field('delete-pin','Parent passcode','password','','required inputmode="numeric"')}${field('delete-word','Type DELETE','text','','required pattern="DELETE"')}${formEnd('Delete local family')}</form>`);$('#delete-form').onsubmit=async e=>{e.preventDefault();try{await unlock('parent',$('#delete-pin').value);localStorage.removeItem(KEY);localStorage.removeItem(PINKEY);state=null;actor=null;close();render();toast('The local family was removed. Only an exported backup can preserve its records.');}catch(e){error(e.message);}};}
function exportData(){if(!parent())return;const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='PocketCrew-family-records.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Export contains family records, not passcodes. Keep it private.');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page){page=b.dataset.page;render();window.scrollTo(0,0);$('#main').focus();return;}if(b.dataset.tab){tab=b.dataset.tab;render();return;}if(b.dataset.preset!==undefined){close();workForm(presets[Number(b.dataset.preset)]);return;}const id=b.dataset.id;const actions={demo:startDemo,'new-family':newFamily,switch:switchProfile,lock, 'create-work':()=>workForm(),presets:showPresets,'add-child':()=>childForm(),'edit-child':()=>childForm(id),'remove-child':()=>removeChildForm(id),start:()=>mutation(s=>startWork(s,actor,id),'You’ve started. Come back when it’s ready.'),submit:()=>submitForm(id),review:()=>reviewForm(id),payday:paydayForm,purchase:purchaseForm,goal:goalForm,'reset-pin':()=>pinForm(id),schedule:scheduleForm,delete:deleteForm,export:exportData};actions[b.dataset.act]?.();});
$('#install').onclick=async()=>{if(matchMedia('(display-mode: standalone)').matches||navigator.standalone){toast('PocketCrew is already running from your Home Screen.');return;}if(installPrompt){await installPrompt.prompt();installPrompt=null;return;}modal('Put PocketCrew on Home Screen',`<p>On your iPhone or iPad, open this page in <strong>Safari</strong>.</p><ol class="install-steps"><li>Tap <strong>Share</strong> (the square with an upward arrow). It may be inside the browser menu.</li><li>Choose <strong>Add to Home Screen</strong>. Scroll down if you don’t see it.</li><li>If offered, turn on <strong>Open as Web App</strong>, then tap <strong>Add</strong>.</li><li>Tap the green PocketCrew icon on your Home Screen.</li></ol><p class="subtle">Add the app first, then create your family inside it. Safari and the Home Screen app may keep separate local data. On other devices, use your browser’s Install app or Add to Home Screen option.</p>`);};
bindInstallVisibility($('#install'));
document.addEventListener('click',async event=>{
  const button=event.target.closest('[data-act="check-updates"]');if(!button)return;
  button.disabled=true;button.textContent='Checking for updates…';
  try{await checkForUpdates();}catch(error){toast(error.message);button.disabled=false;button.textContent='Check for updates';}
});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
window.addEventListener('storage',e=>{if(state?.cloud)return;if(e.key===KEY){try{state=JSON.parse(e.newValue);if(!state||(!parent()&&actor&&!state.children.some(c=>c.id===actor)))actor=null;close();render();}catch{lock();}}if(e.key===PINKEY)lock();});
// Account sessions survive app switching. Profile locking is a separate explicit action.
const connection=()=>{$('#connection').textContent=navigator.onLine?'':'Offline — your local family still works.';};window.addEventListener('online',connection);window.addEventListener('offline',connection);
if('serviceWorker' in navigator)navigator.serviceWorker.register('/app/sw.js',{scope:'/app/'}).catch(()=>toast('Offline setup was unavailable. You can still use PocketCrew online.'));
render();connection();
document.addEventListener('click',e=>{const b=e.target.closest('button');const actions={'cloud-login':cloudLogin,'cloud-reload':()=>refreshCloud(),'cloud-join':joinCloud,'cloud-signout':disconnectCloud,'child-join':()=>childJoin(),'child-invite':childInvite};actions[b?.dataset.act]?.();});
const incomingChild=new URLSearchParams(location.hash.slice(1)).get('child');
const recoveryLink=new URLSearchParams(location.hash.slice(1)).get('type')==='recovery';
if(!recoveryLink&&incomingChild){history.replaceState(null,'','/app/');childJoin(incomingChild);}else if(!recoveryLink&&localStorage.getItem('pocketcrew.child-invitation')){childJoin(localStorage.getItem('pocketcrew.child-invitation'));}
readPasswordRecovery().then(recovering=>recovering?'recovery':completeSignIn()).then(connected=>{if(connected==='recovery'){resetPasswordForm();return;}if(!incomingChild&&(connected||restoreSavedSession()))return openCloud(!connected);}).catch(e=>{modal('Sign-in needs attention',`<p>${esc(e.message)}</p><button class="button-full" id="retry-cloud">Try sign-in again</button>`);$('#retry-cloud').onclick=cloudLogin;});
installCloudActions({esc,money,modal,close,toast,state:()=>state,actor:()=>actor,access:()=>childAccess,generation:()=>cloudGeneration,setupPin:setupCloudPin,hasPin:()=>!!readPins()[cloudParentKey()],checkPin:pin=>unlock(cloudParentKey(),pin),accept:next=>{if(!state?.cloud||state.id!==next.id||next.revision<state.revision)return;state=next;render();}});
installShopping({esc,money,modal,close,toast,state:()=>state,actor:()=>actor,access:()=>childAccess,generation:()=>cloudGeneration,
  setupPin:setupCloudPin,hasPin:()=>!!readPins()[state?.cloud?cloudParentKey():'parent'],checkPin:pin=>unlock(state?.cloud?cloudParentKey():'parent',pin),
  accept:next=>{if(!state?.cloud||state.id!==next.id||next.revision<state.revision)return;state=next;render();},
  local:async fn=>{
    const expected=state,acting=actor;
    const save=()=>{const disk=JSON.parse(localStorage.getItem(KEY));if(!disk||disk.id!==expected.id||disk.revision!==expected.revision||actor!==acting)throw Error('Your family changed. Close and refresh before trying again.');const next=structuredClone(disk);fn(next);next.revision++;localStorage.setItem(KEY,JSON.stringify(next));state=next;render();};
    if(navigator.locks)await navigator.locks.request(KEY,save);else save();
  }});
walkthrough=installWalkthrough({family:()=>state?.id,actor:()=>actor,page:()=>page,navigate:p=>{page=p;render();}});
$('#dialog').addEventListener('close',()=>walkthrough.refresh());
